def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product by inserting K multiplication signs into the number string.

    :param num_str: A string representing the number string.
    :param N: The length of the number string.
    :param K: The number of multiplication signs to insert.
    :return: The maximum product as an integer
    """
    if N == 1 and K == 0:
        return int(num_str)

    num_list = list(map(int, num_str))

    # If K is greater than or equal to N-1, we can partition the number into at most N-1 parts
    if K >= N - 1:
        return int("".join(map(str, num_list)))

    # Otherwise, we need to use dynamic programming to find the maximum product
    dp = [[0] * K for _ in range(N)]

    # Fill the dp table
    for i in range(N):
        for k in range(min(K, i + 1)):
            if k == 0:
                dp[i][k] = int(''.join(map(str, num_list[:i + 1])))
            else:
                dp[i][k] = max(dp[j][k - 1] * int(''.join(map(str, num_list[j + 1:i + 1]))) for j in range(k - 1, i))

    return dp[N - 1][K - 1]

