def count_passing_ways(n: int, m: int) -> int:
    # Initialize a 2D list to store the number of ways to pass the ball
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base case: Initially, there's one way to pass the ball to oneself (0 passes)
    dp[0][0] = 1

    # Fill the dynamic programming table
    for i in range(1, n):
        dp[i][0] = 1  # One way to return to the starting student by not passing (for i != 0)

    for i in range(1, n):
        for j in range(1, m + 1):
            dp[i][j] = (dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]) % 1000000007

    return dp[(n - 1) % n][m] 

