def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest common divisor (GCD)
    and y0 as their least common multiple (LCM).

    :param x0: The GCD that each pair (P, Q) must have.
    :param y0: The LCM that each pair (P, Q) must have.
    :return: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    from math import gcd

    quotient = y0 // x0
    count = 0

    for a in range(1, quotient + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

