def generate_numbers(n, rules) -> int:
    from collections import deque

    # Convert the number to a string for easy digit manipulation
    n_str = str(n)
    length = len(n_str)

    # Initialize the queue with the original number and the set to keep track of unique numbers
    queue = deque([n_str])
    unique_numbers = {n_str}

    while queue:
        current = queue.popleft()

        # Try transforming each digit in the current number
        for i in range(length):
            digit = int(current[i])
            for x, y in rules:
                if digit == x:
                    new_number = current[:i] + str(y) + current[i+1:]

                    # Convert the new number back to an integer and add it to the queue if it's unique
                    new_number_int = int(new_number)
                    if new_number_int not in unique_numbers:
                        unique_numbers.add(new_number_int)
                        queue.append(new_number)

    # Return the count of unique numbers
    return len(unique_numbers)

